WITH Base AS (SELECT * FROM employees WHERE manager_id IS NOT NULL OR level IN ('L1', 'L2')), agg AS (SELECT CASE WHEN YEAR(hire_date) < 2024 THEN 'before_2024' WHEN YEAR(hire_date) = 2024 THEN '2024' ELSE 'after_2024' END AS hire_cohort, MIN(hire_date) AS min_hire_date FROM Base GROUP BY CASE WHEN YEAR(hire_date) < 2024 THEN 'before_2024' WHEN YEAR(hire_date) = 2024 THEN '2024' ELSE 'after_2024' END) SELECT hire_cohort, min_hire_date FROM agg ORDER BY min_hire_date
